// charon-tone (r406): progress tones for Linux installers and first-start
// scripts, before any sound tool is installed. GPL-2.0-or-later.
//
// A static x86-64 Linux program without a C library: it talks to the kernel's
// ALSA devices directly (/dev/snd/controlC*, /dev/snd/pcmC*D*p), so it runs in
// a fresh cloud image, in debian-installer's busybox and in an initramfs alike.
// Charon carries it inside CHARON.EFI (CharonToneBinary.h, generated by
// tools/build-charon-tone.py) and writes it beside its scripts.
//
//   charon-tone FREQ MS [FREQ MS ...]   tones one after another (FREQ 0 = pause)
//   charon-tone -p PERCENT              NVDA's progress beep: 110 Hz * 2^(PERCENT/25), 40 ms
//   charon-tone -w ...                  the same sound as a WAV file on standard output
//                                       (for `aplay` when the sound card is already in use)
//   charon-tone -u                      only unmute the playback controls
//
// Exit status: 0 played; 2 every sound card is busy (dmix, PipeWire or a
// speech synthesizer holds it: use -w | aplay); 3 no usable sound card;
// 1 wrong arguments.
typedef unsigned char u8;
typedef unsigned short u16;
typedef unsigned int u32;
typedef int i32;
typedef unsigned long u64;
typedef long i64;

static i64 sys3(i64 n,i64 a,i64 b,i64 c) {
    i64 r;
    __asm__ volatile("syscall":"=a"(r):"a"(n),"D"(a),"S"(b),"d"(c):"rcx","r11","memory");
    return r;
}
#define SYS_write 1
#define SYS_open 2
#define SYS_close 3
#define SYS_ioctl 16
#define SYS_exit 60
#define O_WRONLY 1
#define O_RDWR 2
#define O_NONBLOCK 04000
#define EBUSY 16

static void zero(void* p,u64 n) {u8* b=(u8*)p;while(n--)*b++=0;}
static void ones(void* p,u64 n) {u8* b=(u8*)p;while(n--)*b++=0xFF;}
static int contains(const char* s,const char* w) {
    for(;*s;++s) {const char* a=s;const char* b=w;while(*b && *a==*b) {++a;++b;}if(!*b)return 1;}
    return 0;
}

// ---- ALSA kernel interface (include/uapi/sound/asound.h), 64-bit layout ----
struct ctl_id {u32 numid;i32 iface;u32 device,subdevice;char name[44];u32 index;};                       // 64
struct ctl_list {u32 offset,space,used,count;struct ctl_id* pids;u8 reserved[50];};                       // 80
struct ctl_info {struct ctl_id id;i32 type;u32 access,count;i32 owner;i64 min,max,step;u8 rest[104+64];}; // 272
struct ctl_value {struct ctl_id id;u32 indirect;u32 pad;i64 value[128];u8 reserved[128];};                // 1224
struct interval {u32 min,max,flags;};
struct hw_params {
    u32 flags;u32 masks[3][8];u32 mres[5][8];struct interval intervals[12];struct interval ires[9];
    u32 rmask,cmask,info,msbits,rate_num,rate_den;u64 fifo_size;u8 reserved[64];};                        // 608
_Static_assert(sizeof(struct ctl_id)==64,"ctl id");
_Static_assert(sizeof(struct ctl_list)==80,"ctl list");
_Static_assert(sizeof(struct ctl_info)==272,"ctl info");
_Static_assert(sizeof(struct ctl_value)==1224,"ctl value");
_Static_assert(sizeof(struct hw_params)==608,"hw params");
#define CTL_ELEM_LIST 0xc0505510ul
#define CTL_ELEM_INFO 0xc1105511ul
#define CTL_ELEM_READ 0xc4c85512ul
#define CTL_ELEM_WRITE 0xc4c85513ul
#define PCM_HW_PARAMS 0xc2604111ul
#define PCM_PREPARE 0x4140ul
#define PCM_DRAIN 0x4144ul
#define TYPE_BOOLEAN 1
#define TYPE_INTEGER 2
#define ACCESS_WRITE 2

static struct ctl_id ids[256];
static struct ctl_info info;
static struct ctl_value value;
static struct hw_params hw;
static short pcm[48000*2*2];   // at most two seconds per tone
static char path[32];

static void name(const char* prefix,int card,int device,char tail) {
    int n=0;static const char dir[]="/dev/snd/";
    for(const char* s=dir;*s;++s)path[n++]=*s;
    for(const char* s=prefix;*s;++s)path[n++]=*s;
    path[n++]=(char)('0'+card);
    if(device>=0) {path[n++]='D';path[n++]=(char)('0'+device);path[n++]=tail;}
    path[n]=0;
}
// Playback switches on, playback volumes to four fifths. A fresh system often
// starts with everything muted; what is already louder stays as it is.
static void unmute(int card) {
    name("controlC",card,-1,0);
    const int fd=(int)sys3(SYS_open,(i64)path,O_RDWR,0);
    if(fd<0)return;
    struct ctl_list list;zero(&list,sizeof(list));list.space=256;list.pids=ids;
    if(sys3(SYS_ioctl,fd,CTL_ELEM_LIST,(i64)&list)>=0) {
        const u32 n=list.used<256?list.used:256;
        for(u32 i=0;i<n;++i) {
            const char* nm=ids[i].name;
            const int sw=contains(nm,"Playback Switch"),vol=contains(nm,"Playback Volume");
            if(!sw && !vol)continue;
            if(contains(nm,"Mic") || contains(nm,"Capture") || contains(nm,"Beep") || contains(nm,"Loopback") || contains(nm,"IEC958"))continue;
            zero(&info,sizeof(info));info.id=ids[i];
            if(sys3(SYS_ioctl,fd,CTL_ELEM_INFO,(i64)&info)<0 || !(info.access&ACCESS_WRITE) || info.count>128)continue;
            zero(&value,sizeof(value));value.id=ids[i];
            if(sys3(SYS_ioctl,fd,CTL_ELEM_READ,(i64)&value)<0)continue;
            int changed=0;
            for(u32 c=0;c<info.count;++c) {
                if(sw && info.type==TYPE_BOOLEAN && !value.value[c]) {value.value[c]=1;changed=1;}
                if(vol && info.type==TYPE_INTEGER) {
                    const i64 want=info.min+(info.max-info.min)*4/5;
                    if(value.value[c]<want) {value.value[c]=want;changed=1;}
                }
            }
            if(changed)sys3(SYS_ioctl,fd,CTL_ELEM_WRITE,(i64)&value);
        }
    }
    sys3(SYS_close,fd,0,0);
}
static void set_interval(int param,u32 v) {hw.intervals[param-8].min=hw.intervals[param-8].max=v;hw.intervals[param-8].flags=4;}   // integer
static int configure(int fd,u32 rate,u32 channels) {
    zero(&hw,sizeof(hw));
    ones(hw.masks,sizeof(hw.masks));ones(hw.mres,sizeof(hw.mres));
    for(int i=0;i<12;++i) {hw.intervals[i].min=0;hw.intervals[i].max=0xFFFFFFFFu;hw.intervals[i].flags=0;}
    for(int i=0;i<9;++i) {hw.ires[i].min=0;hw.ires[i].max=0xFFFFFFFFu;hw.ires[i].flags=0;}
    hw.rmask=0xFFFFFFFFu;hw.cmask=0;hw.info=0xFFFFFFFFu;
    zero(hw.masks[0],32);hw.masks[0][0]=1u<<3;   // access: read/write, interleaved
    zero(hw.masks[1],32);hw.masks[1][0]=1u<<2;   // format: signed 16 bit, little endian
    zero(hw.masks[2],32);hw.masks[2][0]=1u<<0;   // subformat: standard
    set_interval(10,channels);set_interval(11,rate);
    return sys3(SYS_ioctl,fd,PCM_HW_PARAMS,(i64)&hw)>=0;
}

// ---- the sound ----
// 2^(k/25) * 65536 for k = 0..24.
static const u32 step25[25]={65536,67378,69273,71220,73222,75281,77397,79573,81810,84110,86475,88906,91405,
    93975,96617,99333,102126,104997,107949,110984,114104,117312,120610,124000,127486};
static u32 progress_hz(u32 percent) {
    if(percent>100)percent=100;
    u64 f=(u64)110*step25[percent%25];
    f<<=percent/25;
    return (u32)(f>>16);
}
// One tone into pcm[] (stereo): a parabolic sine with a 4 ms attack and release.
static u32 render(u32 hz,u32 ms,u32 rate,u32 channels) {
    if(ms>2000)ms=2000;
    const u32 frames=rate*ms/1000,edge=rate/250;
    for(u32 i=0;i<frames;++i) {
        i64 v=0;
        if(hz) {
            const u32 phase=(u32)(((u64)i*hz*65536/rate)&65535);
            const i64 u=phase<32768?phase:phase-32768;
            v=7000*4*u*(32768-u)/((i64)32768*32768);if(phase>=32768)v=-v;
            if(i<edge)v=v*i/edge;else if(frames-i<edge)v=v*(frames-i)/edge;
        }
        for(u32 c=0;c<channels;++c)pcm[i*channels+c]=(short)v;
    }
    return frames;
}
static int number(const char* s,u32* out) {
    u32 v=0;if(!*s)return 0;
    for(;*s;++s) {if(*s<'0' || *s>'9')return 0;v=v*10+(u32)(*s-'0');if(v>1000000)return 0;}
    *out=v;return 1;
}
static void put(int fd,const void* p,u64 n) {
    const u8* b=(const u8*)p;
    while(n) {const i64 w=sys3(SYS_write,fd,(i64)b,(i64)n);if(w<=0)return;b+=w;n-=(u64)w;}
}
static void le32(u8* at,u32 v) {for(int i=0;i<4;++i)at[i]=(u8)(v>>(8*i));}

static u32 tones[32][2];static u32 count;

static int run(int argc,char** argv) {
    int wav=0,only_unmute=0,i=1;
    for(;i<argc && argv[i][0]=='-';++i) {
        if(argv[i][1]=='w')wav=1;
        else if(argv[i][1]=='u')only_unmute=1;
        else if(argv[i][1]=='p') {u32 p;if(i+1>=argc || !number(argv[++i],&p))return 1;tones[count][0]=progress_hz(p);tones[count][1]=40;++count;}
        else return 1;
    }
    for(;i+1<argc && count<32;i+=2) {if(!number(argv[i],&tones[count][0]) || !number(argv[i+1],&tones[count][1]))return 1;++count;}
    if(only_unmute) {for(int c=0;c<8;++c)unmute(c);return 0;}
    if(!count)return 1;
    const u32 rate=48000;
    if(wav) {
        u32 total=0;for(u32 t=0;t<count;++t)total+=rate*(tones[t][1]>2000?2000:tones[t][1])/1000;
        u8 head[44];zero(head,44);
        head[0]='R';head[1]='I';head[2]='F';head[3]='F';le32(head+4,36+total*4);
        head[8]='W';head[9]='A';head[10]='V';head[11]='E';head[12]='f';head[13]='m';head[14]='t';head[15]=' ';
        le32(head+16,16);head[20]=1;head[22]=2;le32(head+24,rate);le32(head+28,rate*4);head[32]=4;head[34]=16;
        head[36]='d';head[37]='a';head[38]='t';head[39]='a';le32(head+40,total*4);
        put(1,head,44);
        for(u32 t=0;t<count;++t) {const u32 frames=render(tones[t][0],tones[t][1],rate,2);put(1,pcm,(u64)frames*4);}
        return 0;
    }
    // The first sound card whose first playback device opens and takes the format.
    int busy=0;
    for(int device=0;device<2;++device)for(int card=0;card<8;++card) {
        name("pcmC",card,device,'p');
        int fd=(int)sys3(SYS_open,(i64)path,O_WRONLY|O_NONBLOCK,0);
        if(fd==-EBUSY) {busy=1;continue;}
        if(fd<0)continue;
        // Opened without waiting (a busy device answers at once); writing must wait.
        sys3(SYS_close,fd,0,0);
        fd=(int)sys3(SYS_open,(i64)path,O_WRONLY,0);
        if(fd<0) {if(fd==-EBUSY)busy=1;continue;}
        u32 channels=2,r=rate;
        if(!configure(fd,r,channels)) {r=44100;if(!configure(fd,r,channels)) {sys3(SYS_close,fd,0,0);continue;}}
        unmute(card);
        if(sys3(SYS_ioctl,fd,PCM_PREPARE,0)<0) {sys3(SYS_close,fd,0,0);continue;}
        for(u32 t=0;t<count;++t) {const u32 frames=render(tones[t][0],tones[t][1],r,channels);put(fd,pcm,(u64)frames*channels*2);}
        // A short tail of silence: some cards cut the end of a very short sound.
        {const u32 frames=render(0,30,r,channels);put(fd,pcm,(u64)frames*channels*2);}
        sys3(SYS_ioctl,fd,PCM_DRAIN,0);
        sys3(SYS_close,fd,0,0);
        return 0;
    }
    return busy?2:3;
}
__attribute__((used)) static void start_c(i64* sp) {
    const int argc=(int)sp[0];char** argv=(char**)(sp+1);
    sys3(SYS_exit,run(argc,argv),0,0);
    for(;;){}
}
__asm__(".globl _start\n_start:\n  mov %rsp,%rdi\n  and $-16,%rsp\n  call start_c\n");
